 20	// already in the yard is standing, so the next login turns to the sibling.
 21	test('a naked sibling takes the wall order once the first planet\'s wall is already in the yard', function (): void {
 22	    bareWallProfile($this->currentUserId);
 23	
 24	    $home = $this->planetService;
 25	    $this->planetSetObjectLevel('robot_factory', 2);
 26	    $this->planetSetObjectLevel('shipyard', 4);
 27	    $this->planetSetObjectLevel('solar_plant', 30);
