 29	    bareWallOpeningFleet($home);
 30	
 31	    $colony = bareWallBareColony($this->secondPlanetService);
 32	
 33	    foreach ([$home, $colony] as $planet) {
 34	        $planet->updateResourceProductionStats();
 35	        $planet->updateResourceStorageStats();
 36	    }
 37	
 38	    // With no wall anywhere the account places its first order on one of the two planets.
 39	    $first = app(QueueableUnitPlanner::class)->plan($this->currentUserId);
 40	    expect($first)->not->toBeNull()
 41	        ->and($first->reason)->toContain('role:defense:standing');
 42	
 43	    $served = $first->planetId;
 44	    $bare = $served === $home->getPlanetId() ? $colony : $home;
 45	
 46	    // The yard takes the order the way the QueueUnits executor places it: paid for, not yet built.
 47	    app(UnitQueueService::class)->add(
 48	        app(PlanetServiceFactory::class)->make($served, true),
 49	        ObjectService::getObjectByMachineName('rocket_launcher')->id,
 50	        1,
 51	    );
 52	
 53	    $second = app(QueueableUnitPlanner::class)->plan($this->currentUserId);
 54	
 55	    expect($second)->not->toBeNull()
 56	        ->and($second->reason)->toContain('role:defense:standing')
 57	        ->and($second->planetId)->toBe($bare->getPlanetId());
